-- insert-castellon-centers.sql
-- Inserta los 27 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Castello de la Plana capital investigados y humanizados en este sprint.
-- Fuentes primarias: "Centres docents de la Comunitat Valenciana" (Generalitat Valenciana,
-- Conselleria d'Educacio, Universitats i Ocupacio, portal dadesobertes.gva.es), filtrado por
-- localidad IN ('CASTELLÓ DE LA PLANA','GRAU DE CASTELLÓ') (termino municipal completo de
-- Castello de la Plana capital, incluyendo el distrito de El Grao; excluye explicitamente el
-- municipio homonimo "CASTELLÓ" de la provincia de Valencia, CP 46270, presente en la misma
-- fuente autonomica). Complementado con las webs oficiales propias de las 3 escuelas infantiles
-- municipales gestionadas por concesion de servicio publico (EULEN Servicios Sociosanitarios:
-- Chupetes, Biberons, Peücs), las webs oficiales de los 2 centros publicos de titularidad
-- Generalitat (portal.edu.gva.es) y con webs oficiales propias de un subconjunto de centros
-- privados para confirmar servicios concretos del enum CenterService.
-- Ver docs/data-sources-castellon.md y data/enrichment/castellon-centers.json.
--
-- Ambito: unicamente el termino municipal de Castello de la Plana capital (localidad in
-- ('CASTELLÓ DE LA PLANA','GRAU DE CASTELLÓ') en la fuente oficial). "Grau de Castello" (El
-- Grao) es uno de los 6 distritos administrativos oficiales del propio municipio de Castello de
-- la Plana, no un municipio distinto.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla, Palma, Alicante, Malaga, Las Palmas, Cordoba y Granada).
-- No toca ningun centro de ninguna otra ciudad ya integrada.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se actualiza,
-- no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "castellon-de-la-plana" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('castellon-de-la-plana', 'Castellón de la Plana', 'Castellón', 'Comunitat Valenciana')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
